CREATE TABLE delivery_areas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,country_codes jsonb NOT NULL,postal_prefixes jsonb NOT NULL,rate_cents integer NOT NULL CHECK(rate_cents>=0),free_threshold_cents integer CHECK(free_threshold_cents>=0),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
